#!/usr/bin/env bash
# Intent: create
# Domain: github
# Area: agent-app
# Secrets: AGENT_APP_ID, AGENT_APP_PRIVATE_KEY
# Why human: GitHub creates and installs an App only after the signed-in owner confirms in the browser.
#
# Uses the GitHub App manifest flow: you click Create and Install; the App ID
# and private key go straight from GitHub to scripts/secrets/rotate.py without
# a downloaded key file or the key appearing on screen.
#
# Human-only: agents never run scripts under scripts/human/.
#
#
# A wizard walks a human through a manual procedure, step by step.
# Generated by the /wizard skill.
#
# Everything above the "STAGES" marker is the wizard library: do not hand-edit
# it. Author the per-step stages below the marker.

set -euo pipefail

# ──────────────────────────────────────────────────────────────────────────
# Wizard library: delightful, consistent UX, identical across every wizard.
# ──────────────────────────────────────────────────────────────────────────

if [[ -t 1 ]] && command -v tput >/dev/null 2>&1 && [[ "$(tput colors 2>/dev/null || echo 0)" -ge 8 ]]; then
  BOLD=$(tput bold); DIM=$(tput dim); RESET=$(tput sgr0)
  BLUE=$(tput setaf 4); GREEN=$(tput setaf 2); YELLOW=$(tput setaf 3)
else
  BOLD=""; DIM=""; RESET=""; BLUE=""; GREEN=""; YELLOW=""
fi

# Author sets this at the top of the stages section.
TOTAL_STAGES=0

_STAGE_INDEX=0
ENV_FILE="${ENV_FILE:-.env}"
WRITTEN_ENV=()    # KEYs written to ENV_FILE this run
WRITTEN_SECRET=() # secret NAMEs set this run
WRITTEN_VAR=()    # GitHub variable NAMEs set this run
SKIPPED=()        # things we couldn't do (e.g. gh missing)

# _clear wipes the terminal so only the current step is on screen. No-op when
# output isn't a terminal, so piped logs stay readable.
_clear() {
  [[ -t 1 ]] || return 0
  if command -v tput >/dev/null 2>&1 && tput clear 2>/dev/null; then return 0; fi
  printf '\033[2J\033[3J\033[H'
}

# banner "Title" shows the opening frame: what this wizard does.
banner() {
  _clear
  printf '\n%s%s  %s%s\n' "$BOLD" "$BLUE" "$1" "$RESET"
  printf '%s  %s stages%s\n\n' "$DIM" "$TOTAL_STAGES" "$RESET"
  printf '%s  You drive the browser; this wizard tells you exactly what to do and\n' "$DIM"
  printf '  captures the values you copy back. Stop any time with Ctrl-C and re-run\n'
  printf '  later, since it remembers values already saved.%s\n' "$RESET"
  pause "Ready to start?"
}

# stage "Name" clears the screen, then announces a stage and shows progress.
# Clearing keeps only the current step on screen.
stage() {
  _clear
  _STAGE_INDEX=$((_STAGE_INDEX + 1))
  printf '\n%s%s▸ Stage %s/%s · %s%s\n' \
    "$BOLD" "$BLUE" "$_STAGE_INDEX" "$TOTAL_STAGES" "$1" "$RESET"
}

# say "..." prints a plain instruction line.
say()  { printf '  %s\n' "$1"; }
# step "..." is a numbered-feeling action the human takes in the browser.
step() { printf '  %s•%s %s\n' "$BLUE" "$RESET" "$1"; }
note() { printf '  %s%s%s\n' "$DIM" "$1" "$RESET"; }
warn() { printf '  %s⚠ %s%s\n' "$YELLOW" "$1" "$RESET"; }

# open_url URL opens it in the human's browser, cross-platform incl. WSL.
open_url() {
  local url="$1"
  printf '  %s↗ opening%s %s\n' "$GREEN" "$RESET" "$url"
  { if   command -v wslview     >/dev/null 2>&1; then wslview "$url"
    elif command -v explorer.exe >/dev/null 2>&1; then explorer.exe "$url"
    elif command -v xdg-open    >/dev/null 2>&1; then xdg-open "$url"
    elif command -v open        >/dev/null 2>&1; then open "$url"
    else false; fi
  } >/dev/null 2>&1 || warn "couldn't open a browser, so visit it manually: $url"
}

# pause "msg" waits for the human to confirm they've done the manual part.
pause() {
  printf '  %s%s%s ' "$DIM" "${1:-Press Enter to continue}" "$RESET"
  read -r _ || true
}

# confirm "question" is a y/N gate; returns success on yes.
confirm() {
  local reply=""
  printf '  %s? %s [y/N] ' "$YELLOW" "$1"
  read -r reply || true
  [[ "$reply" =~ ^[Yy] ]]
}

# _existing KEY: current value of KEY in ENV_FILE, if any, with write_env's single
# quotes or a plain dotenv double-quoted value undone.
_existing() {
  [[ -f "$ENV_FILE" ]] || return 1
  local line value sq="'\\''"; line=$(grep -E "^${1}=" "$ENV_FILE" | tail -n1) || return 1
  value="${line#*=}"
  if [[ "$value" == \'*\' ]]; then value="${value:1:${#value}-2}"; value="${value//"$sq"/\'}"
  elif [[ "$value" == \"*\" ]]; then
    value="${value:1:${#value}-2}"
    [[ "$value" == *[\\\$\"]* ]] && return 1   # escapes, $ or ": can't decode safely; ask again
  fi
  printf '%s' "$value"
}

# ask KEY "Prompt" reads a value into $KEY. Offers the existing .env value as
# a default on re-runs (Enter keeps it). Visible input (non-secret), edited
# with Readline. Fails at EOF with no input.
ask() {
  local key="$1" prompt="$2" current input s=$'\001' e=$'\002' p rc=0
  current=$(_existing "$key" || true)
  # Readline needs the colour codes wrapped in \001..\002 to place the cursor.
  p="  $s$BOLD$e$prompt$s$RESET$e "
  [[ -n "$current" ]] && p+="$s$DIM$e[Enter keeps current]$s$RESET$e "
  read -e -r -p "$p" input || rc=1
  if (( rc )) && [[ -z "$input" ]]; then return 1; fi
  [[ -z "$input" && -n "$current" ]] && input="$current"
  printf -v "$key" '%s' "$input"
}

# ask_secret KEY "Prompt" is like ask, but input is hidden.
ask_secret() {
  local key="$1" prompt="$2" current input rc=0
  current=$(_existing "$key" || true)
  if [[ -n "$current" ]]; then
    printf '  %s%s%s %s[Enter keeps current]%s ' "$BOLD" "$prompt" "$RESET" "$DIM" "$RESET"
  else
    printf '  %s%s%s ' "$BOLD" "$prompt" "$RESET"
  fi
  read -rs input || rc=1
  printf '\n'
  if (( rc )) && [[ -z "$input" ]]; then return 1; fi
  [[ -z "$input" && -n "$current" ]] && input="$current"
  printf -v "$key" '%s' "$input"
}

# write_env KEY VALUE upserts KEY='VALUE' into ENV_FILE (replaces any existing
# line) and sets $KEY. Idempotent. Creates ENV_FILE at mode 0600; writes through
# a symlink and keeps an existing file's mode.
write_env() {
  local key="$1" value="$2" tmp sq="'\\''"
  [[ -e "$ENV_FILE" ]] || (umask 077 && : > "$ENV_FILE")
  tmp=$(mktemp)
  grep -vE "^${key}=" "$ENV_FILE" > "$tmp" || true
  printf "%s='%s'\n" "$key" "${value//\'/$sq}" >> "$tmp"
  cat "$tmp" > "$ENV_FILE"
  rm -f "$tmp"
  printf -v "$key" '%s' "$value"
  WRITTEN_ENV+=("$key")
  printf '  %s✓ wrote%s %s → %s\n' "$GREEN" "$RESET" "$key" "$ENV_FILE"
}

# set_secret NAME VALUE stores a secret through the repository's rotation
# script, which writes every sink registered for NAME (GitHub, .env). NAME must
# be registered in scripts/secrets/registry.toml with `generate = "manual"`.
# The value reaches rotate.py through an exported variable in a subshell, never
# a command argument, so other local users cannot read it from the process list.
# Falls back to a warning (and records it) if the script cannot store it.
set_secret() {
  local name="$1" value="$2"
  local root
  root="$(git rev-parse --show-toplevel 2>/dev/null || pwd)"
  if ( export "NEW_$name=$value"; exec python3 "$root/scripts/secrets/rotate.py" "$name" ) >/dev/null 2>&1; then
    WRITTEN_SECRET+=("$name")
    printf '  %s✓ set%s secret %s\n' "$GREEN" "$RESET" "$name"
    return
  fi
  SKIPPED+=("secret $name (store it later: scripts/secrets/rotate.py $name)")
  warn "skipped secret $name: rotate.py could not store it; set it later"
}

# set_var NAME VALUE sets a GitHub Actions repo variable (non-secret).
set_var() {
  local name="$1" value="$2"
  if command -v gh >/dev/null 2>&1 && gh auth status >/dev/null 2>&1; then
    if gh variable set "$name" --body "$value" >/dev/null 2>&1; then
      WRITTEN_VAR+=("$name")
      printf '  %s✓ set%s GitHub variable %s\n' "$GREEN" "$RESET" "$name"
      return
    fi
  fi
  SKIPPED+=("GitHub variable $name")
  warn "skipped GitHub variable $name, gh not ready; set it later"
}

# finish clears, then shows a closing summary of everything configured.
finish() {
  _clear
  printf '\n%s%s  ✓ Setup complete%s\n' "$BOLD" "$GREEN" "$RESET"
  (( ${#WRITTEN_ENV[@]} ))    && note "wrote ${#WRITTEN_ENV[@]} value(s) to $ENV_FILE: ${WRITTEN_ENV[*]}"
  (( ${#WRITTEN_SECRET[@]} )) && note "set ${#WRITTEN_SECRET[@]} GitHub secret(s): ${WRITTEN_SECRET[*]}"
  (( ${#WRITTEN_VAR[@]} ))    && note "set ${#WRITTEN_VAR[@]} GitHub variable(s): ${WRITTEN_VAR[*]}"
  if (( ${#SKIPPED[@]} )); then
    printf '\n'; warn "still to do by hand:"
    for s in "${SKIPPED[@]}"; do note "  - $s"; done
  fi
  printf '\n'
}

# ──────────────────────────────────────────────────────────────────────────
# STAGES: author this section. One stage() per step the human takes.
# Replace the example below. Set TOTAL_STAGES to match the stages you write.
# Keep every stage inside run_wizard and the last line as is: bash then parses
# the whole file before the first prompt, so an edit mid-run can't break it.
# ──────────────────────────────────────────────────────────────────────────

run_wizard() {
[[ -t 0 && -t 1 ]] || { echo "scripts/human: interactive only; run it yourself in a terminal" >&2; exit 2; }

TOTAL_STAGES=2
REPO_SLUG="$(git remote get-url origin 2>/dev/null | sed -E 's#(git@github.com:|https://github.com/)##; s#\.git$##')"
REPO_SLUG="${REPO_SLUG:-JoachimTislov/foodsavr}"
REPO_NAME="${REPO_SLUG#*/}"
WORK="$(mktemp -d)"
SERVER_PID=""
trap 'rm -rf "$WORK"; [[ -n "$SERVER_PID" ]] && kill "$SERVER_PID" 2>/dev/null; true' EXIT

banner "Agent GitHub App"

stage "Create the App (one click)"
say "A local page sends GitHub a prefilled App definition: Contents, Issues,"
say "Pull requests, Checks = read and write; Metadata = read; no Workflows"
say "permission (agent patches cannot change CI); no webhook; private to you."
STATE="$(python3 -c 'import secrets; print(secrets.token_urlsafe(16))')"
PORT="$(python3 -c 'import socket; s = socket.socket(); s.bind(("127.0.0.1", 0)); print(s.getsockname()[1]); s.close()')"
python3 - "$PORT" "$STATE" "$REPO_SLUG" "$REPO_NAME" "$WORK" <<'PY' &
import html, http.server, json, sys, urllib.parse

port, state, repo, name, work = int(sys.argv[1]), sys.argv[2], sys.argv[3], sys.argv[4], sys.argv[5]
manifest = {
    "name": f"{name}-agent",
    "url": f"https://github.com/{repo}",
    "redirect_url": f"http://127.0.0.1:{port}/callback",
    "public": False,
    "default_permissions": {"contents": "write", "issues": "write", "pull_requests": "write", "checks": "write", "metadata": "read"},
    "default_events": [],
}
page = (
    f'<form id="f" method="post" action="https://github.com/settings/apps/new?state={state}">'
    f'<input type="hidden" name="manifest" value="{html.escape(json.dumps(manifest))}"></form>'
    '<script>document.getElementById("f").submit()</script>'
)


class Handler(http.server.BaseHTTPRequestHandler):
    def log_message(self, *args):
        pass

    def do_GET(self):
        url = urllib.parse.urlparse(self.path)
        query = urllib.parse.parse_qs(url.query)
        if url.path == "/":
            body = page
        elif url.path == "/callback" and query.get("state", [""])[0] == state and query.get("code"):
            with open(f"{work}/code", "w") as handle:
                handle.write(query["code"][0])
            body = "App created. Return to the terminal."
        else:
            self.send_response(400)
            self.end_headers()
            return
        self.send_response(200)
        self.send_header("Content-Type", "text/html")
        self.end_headers()
        self.wfile.write(body.encode())


http.server.HTTPServer(("127.0.0.1", port), Handler).serve_forever()
PY
SERVER_PID=$!
open_url "http://127.0.0.1:${PORT}/"
step "GitHub shows the App form. Rename it if the name is taken, then click 'Create GitHub App'."
say "Waiting for GitHub to send you back (up to 10 minutes)..."
for _ in $(seq 600); do [[ -s "$WORK/code" ]] && break; sleep 1; done
kill "$SERVER_PID" 2>/dev/null || true
SERVER_PID=""
[[ -s "$WORK/code" ]] || { warn "No confirmation from GitHub; re-run the wizard."; exit 1; }
python3 - "$WORK" <<'PY'
import json, os, sys, urllib.request

work = sys.argv[1]
code = open(f"{work}/code").read().strip()
request = urllib.request.Request(
    f"https://api.github.com/app-manifests/{code}/conversions",
    method="POST",
    headers={"Accept": "application/vnd.github+json", "User-Agent": "foodsavr-human-setup"},
)
data = json.load(urllib.request.urlopen(request, timeout=30))
for key in ("id", "slug"):
    with open(f"{work}/{key}", "w") as handle:
        handle.write(str(data[key]))
descriptor = os.open(f"{work}/pem", os.O_WRONLY | os.O_CREAT | os.O_TRUNC, 0o600)
os.write(descriptor, data["pem"].encode())
os.close(descriptor)
PY
AGENT_APP_SLUG="$(cat "$WORK/slug")"
set_secret AGENT_APP_ID "$(cat "$WORK/id")"
set_secret AGENT_APP_PRIVATE_KEY "$(cat "$WORK/pem")"
set_var AGENT_APP_SLUG "$AGENT_APP_SLUG"
rm -f "$WORK/pem"

stage "Install the App on ${REPO_NAME}"
open_url "https://github.com/apps/${AGENT_APP_SLUG}/installations/new"
step "Choose your account, then 'Only select repositories' and pick ${REPO_NAME}. Click Install."
pause "Installed?"
say "Agent runs now publish as ${AGENT_APP_SLUG}[bot], and their PRs run CI."
note "Rotate later: App settings > Private keys > Generate, then scripts/secrets/rotate.py AGENT_APP_PRIVATE_KEY."

finish
}

run_wizard "$@"; exit
